B.jc=new A.ae(58173,"MaterialIcons",null,!1)
B.byC=new A.a2i("Estimativa com os escal\xf5es de IRS de 2026 e 11 % de Seguran\xe7a Social, corrigida pela reten\xe7\xe3o real do seu emprego atual. Valores para orienta\xe7\xe3o; confirme com o recibo da nova empresa.",!1,B.jc,null)
